# Look for config files or scripts in parent directories
import os

def find_config_files(base_dir, depth=3):
    """Find config-like files within depth directories"""
    results = []
    current = base_dir
    for _ in range(depth):
        print(f"\nScanning: {current}")
        if os.path.exists(os.path.join(current, 'config.yaml')):
            results.append(os.path.join(current, 'config.yaml'))
        if os.path.exists(os.path.join(current, 'input.txt')):
            results.append(os.path.join(current, 'input.txt'))
        if os.path.exists(os.path.join(current, 'input.json')):
            results.append(os.path.join(current, 'input.json'))

        # Check subdirectories
        subdir = os.path.join(current, '..') if depth < 3 else None
        if subdir and os.path.exists(subdir) and not subdir.endswith('workspace'):
            print(f"  Up one level to: {subdir}")
        else:
            break

        if depth > 1:
            subdir_path = os.path.dirname(current)
            if not subdir_path == current:
                results.extend(find_config_files(subdir_path, depth-1))

    return results

